using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePoints = 10;

    public int For(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        var ratePoints = Math.Min(BaseRatePoints(loyaltyTier) + BonusPoints(subtotalCents), MaxRatePoints);
        var discountCents = (int)((long)subtotalCents * ratePoints / 100);
        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null),
    };

    private static int BonusPoints(int subtotalCents) =>
        subtotalCents >= 20_000 ? 3 : subtotalCents >= 5_000 ? 1 : 0;
}
